#!/usr/bin/env python3
"""Localize links only to pages already generated by the unpublished static pilot.

No link is allowed to create a new route, bypass publication policy, or copy
content from the production website. Unknown destinations stay on production.
"""
from __future__ import annotations

import html
import hashlib
import json
import posixpath
import re
from collections import Counter
from pathlib import Path
from urllib.parse import unquote, urlsplit, parse_qs
from functools import lru_cache
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent))
import build_github_pages_legal_details_pilot as legal
import build_github_pages_qa_details_pilot as qa

ORIGIN = "kaigo-rules.vercel.app"
ATTR = re.compile(r'(\bhref=")([^"]+)(")')
SAFE_SERVICE = re.compile(r"^[a-z0-9-]+$")
SAFE_CHAPTER = SAFE_SERVICE
SAFE_FRAGMENT = re.compile(r"^[A-Za-z0-9_.:-]+$")
# Only the known legacy fee-unit-price link is turned into a clearly labelled
# static search fallback. The static search does not provide a unit-price table.
UNIT_PRICE_LINK = re.compile(
    r'(?P<open><a\b[^>]*\bhref="https://kaigo-rules\.vercel\.app/fees/unit-price"[^>]*>)'
    r'(?P<body>(?:(?!</a>).){0,800})</a>',
    re.DOTALL,
)
UNIT_PRICE_FALLBACK_LABEL = "地域区分の関連資料を検索（一単位単価表ではありません）"



@lru_cache(maxsize=4)
def _legislation_index(path: str):
    """Only a bounded publishable record-id and applicability manifest."""
    file = Path(path)
    if not file.is_file() or file.is_symlink():
        return {}
    data = json.loads(file.read_text(encoding="utf-8"))
    if not isinstance(data, dict) or len(data) > 100000:
        raise RuntimeError("Invalid static legislation record manifest")
    return data


def _legislation_record(root: Path, query: str):
    try:
        params = parse_qs(query, strict_parsing=True, keep_blank_values=True, max_num_fields=8)
    except ValueError:
        return None
    if not params or "record" not in params or set(params) - {"record", "service", "category", "document"}:
        return None
    if any(len(values) != 1 for values in params.values()):
        return None
    identifier = params["record"][0]
    if not 1 <= len(identifier) <= 2048 or any(ord(ch) < 32 or ord(ch) == 127 for ch in identifier):
        return None
    record_index = _legislation_index(str(root / "legislation" / "record-index.json"))
    entry = record_index.get(identifier)
    if not isinstance(entry, dict) or set(entry) != {"document", "category", "services"}:
        return None
    if any(params.get(key, [entry[prop]])[0] != entry[prop]
           for key, prop in (("document", "document"), ("category", "category"))):
        return None
    if params.get("service") and params["service"][0] not in entry["services"]:
        return None
    return root / "legislation" / "record" / (hashlib.sha256(identifier.encode("utf-8")).hexdigest() + ".html")


def _legislation_browse(root: Path, query: str):
    if not query:
        return root / "legislation" / "index.html"
    try:
        params = parse_qs(query, strict_parsing=True, keep_blank_values=True, max_num_fields=8)
    except ValueError:
        return None
    if not params or set(params) - {"service", "category", "document", "q", "page"}:
        return None
    if any(len(values) != 1 or len(values[0]) > 300 for values in params.values()):
        return None
    if "page" in params and (not params["page"][0].isdigit() or not 1 <= int(params["page"][0]) <= 10000):
        return None
    if "service" in params and params["service"][0] and not SAFE_SERVICE.fullmatch(params["service"][0]):
        return None
    if "category" in params and params["category"][0] not in {
        "law", "standards", "notices", "remuneration", "guidance", "criteria", ""
    }:
        return None
    if "document" in params and params["document"][0] and not re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9._:-]{0,180}", params["document"][0]
    ):
        return None
    return root / "legislation" / "index.html"


def destination(root: Path, href: str) -> tuple[str, Path, str] | None:
    parts = urlsplit(href)
    if (parts.scheme != "https" or parts.netloc != ORIGIN or parts.username
            or parts.password or not parts.path.startswith("/")):
        return None
    decoded = unquote(parts.path)
    if any(c in decoded for c in ("\\", "\x00")) or "/../" in decoded or decoded.endswith("/.."):
        return None
    path = decoded.rstrip("/") or "/"
    query = parts.query
    kind = ""
    target = None
    suffix = ""

    if path in {"/", "/services"} and not query:
        kind, target = "home", root / "index.html"
    elif path == "/databases/search":
        kind, target, suffix = "search", root / "databases/search/index.html", ("?" + query if query else "")
    elif path == "/qa":
        kind, target, suffix = "qa-search", root / "databases/search/qa.html", ("?" + query if query else "")
    elif path == "/legislation":
        if "record=" in query:
            kind, target = "legislation-record", _legislation_record(root, query)
        else:
            kind, target = "legislation-browse", _legislation_browse(root, query)
            if target is not None and query:
                suffix = "?" + query
    elif path == "/rules":
        sid = ""
        try:
            params = parse_qs(query, strict_parsing=False, keep_blank_values=False, max_num_fields=4)
            if "service" in params and SAFE_SERVICE.fullmatch(params["service"][0]):
                sid = params["service"][0]
        except Exception:
            pass
        q = f"service={sid}&category=standards" if sid else "category=standards"
        kind, target, suffix = "legislation-browse", _legislation_browse(root, q), "?" + q
    elif path == "/notices":
        sid = ""
        try:
            params = parse_qs(query, strict_parsing=False, keep_blank_values=False, max_num_fields=4)
            if "service" in params and SAFE_SERVICE.fullmatch(params["service"][0]):
                sid = params["service"][0]
        except Exception:
            pass
        q = f"service={sid}&category=notices" if sid else "category=notices"
        kind, target, suffix = "legislation-browse", _legislation_browse(root, q), "?" + q
    elif path == "/fees/criteria":
        kind, target, suffix = "legislation-browse", _legislation_browse(root, "category=criteria"), "?category=criteria"
    elif path == "/fees/unit-price":
        kind, target, suffix = "search", root / "databases/search/index.html", "?q=%E5%9C%B0%E5%9F%9F%E5%8C%BA%E5%88%86"
    elif path in {"/start", "/overview", "/guide", "/sources", "/handbook-sources",
                  "/fees/guidance", "/fees"} and not query:
        kind, target = "information", root / path.lstrip("/") / "index.html"
    else:
        match = re.fullmatch(r"/services/([a-z0-9-]+)", path)
        if match and not query:
            kind, target = "services", root / "services" / match[1] / "index.html"
        match = re.fullmatch(r"/services/([a-z0-9-]+)/remuneration", path)
        if match and not query:
            kind, target = "handbook", root / "handbook" / match[1] / "remuneration.html"
        match = re.fullmatch(r"/services/([a-z0-9-]+)/remuneration/guidance", path)
        if match and not query:
            service_id = match[1]
            if service_id == "dayservice":
                # This existing page covers dayservice alone; never attribute it to another service.
                kind, target = "information", root / "fees/guidance/index.html"
            elif (root / "handbook" / service_id / "remuneration.html").is_file():
                # Scoped source browser, not a substitute for verified fee guidance.
                q = f"service={service_id}&category=guidance"
                kind, target, suffix = "legislation-browse", _legislation_browse(root, q), "?" + q
        match = re.fullmatch(r"/services/([a-z0-9-]+)/rules", path)
        if match and not query:
            q = f"service={match[1]}&category=standards"
            kind, target, suffix = "legislation-browse", _legislation_browse(root, q), "?" + q
        match = re.fullmatch(r"/services/([a-z0-9-]+)/notices", path)
        if match and not query:
            q = f"service={match[1]}&category=notices"
            kind, target, suffix = "legislation-browse", _legislation_browse(root, q), "?" + q
        match = re.fullmatch(r"/handbook/([a-z0-9-]+)/([a-z0-9-]+)", path)
        if match and not query:
            kind, target = "handbook", root / "handbook" / match[1] / (match[2] + ".html")
        match = re.fullmatch(r"/qa/([A-Za-z0-9][A-Za-z0-9._-]{0,120})", path)
        if match and query in {"", "reader=1"}:
            kind = "qa-detail"
            target = root / "databases/search/qa-details" / match[1] / (
                "reader.html" if query == "reader=1" else "index.html")
        match = re.fullmatch(r"/fees/([a-z0-9]+(?:[.-][a-z0-9]+)*)", path)
        if match and not query:
            kind = "fee-detail"
            target = root / "fees" / match[1] / "index.html"
        try:
            key = legal.key_from_href(path + ("?" + query if query else ""))
        except ValueError:
            key = None
        if key:
            kind, target = "legal-detail", root / "databases/search" / legal.local_path(key)

    if not target or not target.is_file() or target.is_symlink():
        return None
    # Keep fragments only when the generated target contains the exact ID.
    if parts.fragment:
        fragment = unquote(parts.fragment)
        if not SAFE_FRAGMENT.fullmatch(fragment):
            return None
        target_text = target.read_text(encoding="utf-8")
        if not re.search(r'\bid="' + re.escape(html.escape(fragment, quote=True)) + r'"', target_text):
            return None
    else:
        fragment = ""
    return kind, target, suffix + (("#" + fragment) if fragment else "")


def localize(root: Path) -> dict:
    if not root.is_dir() or root.is_symlink():
        raise RuntimeError("Missing or symbolic-link pilot directory")
    pages = list(root.rglob("*.html"))
    if any(p.is_symlink() for p in pages):
        raise RuntimeError("Symlink in generated HTML")
    counts = Counter()
    changed = 0
    links = 0
    for source in pages:
        content = source.read_text(encoding="utf-8")
        original_content = content

        def replace_unit_price_anchor(match):
            nonlocal links
            current = "https://" + ORIGIN + "/fees/unit-price"
            found = destination(root, current)
            if not found:
                return match[0]
            kind, target, suffix = found
            relative = posixpath.relpath(target.relative_to(root).as_posix(),
                                       source.parent.relative_to(root).as_posix() or ".")
            new_href = html.escape(relative + suffix, quote=True)
            opening = match["open"].replace(
                'href="' + current + '"', 'href="' + new_href + '"', 1)
            if opening == match["open"]:
                raise RuntimeError("Unit-price fallback link could not be rewritten")
            links += 1
            counts[kind] += 1
            return opening + UNIT_PRICE_FALLBACK_LABEL + "</a>"

        # A search fallback must never retain a label claiming to show a price table.
        content = UNIT_PRICE_LINK.sub(replace_unit_price_anchor, content)

        def replace(match):
            nonlocal links
            current = html.unescape(match[2])
            if not current.startswith("https://" + ORIGIN + "/"):
                return match[0]
            # Unknown anchor shapes must not be relabelled as price tables.
            if current == "https://" + ORIGIN + "/fees/unit-price":
                return match[0]
            found = destination(root, current)
            if not found:
                return match[0]
            kind, target, suffix = found
            relative = posixpath.relpath(target.relative_to(root).as_posix(),
                                       source.parent.relative_to(root).as_posix() or ".")
            links += 1
            counts[kind] += 1
            new_href = html.escape(relative + suffix, quote=True)
            return match[1] + new_href + match[3]

        updated = ATTR.sub(replace, content)
        if updated != original_content:
            source.write_text(updated, encoding="utf-8")
            changed += 1
    return {"pages_scanned": len(pages), "pages_changed": changed,
            "links_localized": links, "by_destination": dict(sorted(counts.items()))}
